-- Generated by `make contracts` from contracts/control_plane/condition_crosswalk.odcs.yaml. Do not edit: change the contract and regenerate.
-- The latest export only. optional_source gives an empty table while no export exists.
with raw as (
    select * from {{ optional_source('control_plane', 'condition_crosswalk') }}
),

latest as (
    select * from raw where filename = (select max(filename) from raw)
)

select
  "record_id" AS "record_id",
  "dataset" AS "dataset",
  "label" AS "label",
  "state" AS "state",
  "mesh_id" AS "mesh_id",
  "ncbi_taxon_id" AS "ncbi_taxon_id",
  "gbd_cause" AS "gbd_cause",
  "synonym" AS "synonym",
  "proposed_by" AS "proposed_by",
  "source" AS "source",
  "reviewer" AS "reviewer",
  CAST(CAST(NULLIF(trim("reviewed_at"), '') AS TIMESTAMP) AS DATE) AS "reviewed_at",
  "note" AS "note"
from latest
